update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p041","body":"ابھی جو دل اداس ہے\nکوئی نہ آس پاس ہے\nنہ راہبر، نہ راہگزر\nکوئی نہیں جو خاص ہے\nنہیں کوئی قلم کی نوک پہ\nنہ نظر میں کوئی نہ کھوج میں\nیونہی بہہ رہی ہے  یہ زندگی\nجانے کون سی سمت کس موج میں\nابھی جو زندگی شاد نہیں\nوہ جنوں کے دن کچھ یاد نہیں\nوہ خلش جو جگر کی پیاس تھی\nاس کی بھی باقی میعاد نہیں\nابھی خزاں رسیدہ جو دل کا حال ہے\nیہ آخر کبھی تو بدل جائے گا\nتجھے تلاش جس بہار کی ہے\nوہ نہ بھی آئی تو سنبھل جائے گا"},{"slug":"tum-p042","body":"یاد کروں جب وہ گزرے دن\nتو ادھوری سی کچھ باتیں ہیں\nکچھ شوخ بھری کہانیاں ہیں\nکچھ دھندلی دھندلی یادیں ہیں\n\nجب سوچنے بیٹھا تو یاد آئے\nایک تنگ گلی کا کچا گھر\nکچی چھتوں پہ پکے دوست\nکرکٹ ، بسنت  اور دوپہر\n\nسکول کی بریک اور لوڈ شیڈنگ\nاور ٹویشن میں سر کی مار بھی\nوہ چھپ چھپ کے گیمنگ زون جانا\nاور وہ سنوکر کلب کے یار بھی\n\nیاد کروں تو یاد آئے مجھے\nوہ زندگی کی پہلی آس\nوہ پہلا پہلا ادھورا عشق\nوہ جلتے دل کی پہلی کاش\n\nاب زندگی کی ویرانیوں میں\nایسے کھوئے کہ نہ شور آئے\nیادیں ابھی بھی باقی ہیں\nہم وہ شہر بس چھوڑ آئے"},{"slug":"tum-p043","body":"وہ کوئی جو تار دل کے دل سے ملائے جائے\nیوں دل لگانا چاہے مگر دل ہی جلائے جائے\n\nوہ حقیقت ہی کیا جو نہ کرے زمانہ تسلیم\nوہ خواب کیا دیکھیے جو بےدھڑک سنائے جائے\n\nانھیں اپنا کہیں جنھیں این و آں کی  نہ ہو خبر\nوہ غیر سہی جو نہ بن بلائے ستائے جائے\n\nجنوں اتنا کہ زمانہ سارا لگے ہے مٹانے کو\nمقدر ایسا کہ ایک شخص نہ منائے جائے\n\nزخم ایسے کہ نہ ہو عیاں دن سویر میں\nگھاؤ ایسے کہ شب بھر نہ بھلائے جائے\n\nیاد ہے ترک تعلق کو ہوئے اگرچہ کئی برس\nاحمد مگر کیا کیجیے جب دل کسی پہ آئے جائے"},{"slug":"tum-p044","body":"لبوں پہ ہنسی اور آنکھ پرنم ہے، تو کیا غم ہے\nبزم جاں جو اب غیر کی بزم ہے ، تو کیا غم ہے\n\nاگرچہ اس تغافل کے اسباب ہیں بہت\nدل کو تیری چاہت کا بھرم ہے، تو کیا غم ہے\n\nکیا ہوا جو بچھڑے ہیں دل لگی کے اس دور میں\nیہ محبت کی دیرینہ رسم ہے، تو کیا غم ہے\n\nاور بھی تو کئی ثروتوں سے سرشار ہے زندگی\nبس ایک تیری فرقت کا غم ہے ، تو کیا غم ہے"},{"slug":"tum-p045","body":"کبھی تو قرار دل کی وسعتوں سے ہو گزرے\nکبھی تو ہو میسر وہ کہ جس کی ہم نے کی تلاش\nکبھی تو یہ جملے مکمل ادا ہوں اس طرح سے\nکہ باقی نہ رہے کوئی آس نہ کوئی حرفِ کاش\n\nکبھی تو بہاریں لوٹ آئیں گی اجڑے چمن میں اپنے\nکبھی تو ختم کہانیاں بھی ادھوری ہو ہی جائیں گی\nپھر ہوگا سکوں کا پل میسر ان ادھوری داستانوں کو\nیہ آرزوئیں یہاں نہیں پر کہیں تو پوری ہو ہی جائیں گی"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
